const trig = $('WhatsApp Trigger').first().json;
const msg = (trig.messages || [])[0] || {};
const contact = (trig.contacts || [])[0] || {};
const rows = $input.all().map(i => i.json).filter(r => r && r.phone);
const existing = rows[0] || {};
const phone = String(msg.from || '');
const type = msg.type || 'unknown';

let text = '';
let replyId = '';
if (type === 'text') text = (msg.text && msg.text.body) || '';
else if (type === 'interactive') {
  const it = msg.interactive || {};
  text = (it.list_reply && it.list_reply.title) || (it.button_reply && it.button_reply.title) || '';
  replyId = (it.list_reply && it.list_reply.id) || (it.button_reply && it.button_reply.id) || '';
} else if (type === 'button') text = (msg.button && msg.button.text) || '';
else if (type === 'image') text = (msg.image && msg.image.caption) || '';
text = String(text).trim();

const fullStage = String(existing.stage || '').trim();
const pm = fullStage.match(/^(hi|ta|te|en):/);
let lang = pm ? pm[1] : 'en';
const rawStage = fullStage.replace(/^(hi|ta|te|en):/, '');
const stage = rawStage.split('#')[0];
const tries = parseInt(rawStage.split('#')[1] || '0', 10) || 0;
const lower = text.toLowerCase();
const wantsHuman = /\b(human|person|agent|executive|representative|sales|associate|associative|staff|owner|manager|someone|call me|call back|callback|talk|speak|baat)\b/.test(lower);
const wantsInfo = /\b(more info|info|information|details|detail|explain|help|query|question|doubt|confused|confusing|samajh)\b|not understand|don'?t understand|didn'?t understand|\?/.test(lower);
const wantsHumanHi = /(बात|इंसान|सेल्स|कॉल|फोन|मैनेजर|मालिक|एजेंट|किसी से|பேச|மனிதர்|கால்|போன்|அழைக்க|மேனேஜர்|మాట్లాడ|మనిషి|కాల్|ఫోన్|మేనేజర్)/.test(text);
const wantsInfoHi = /(जानकारी|मदद|समझ|सवाल|डिटेल|बताइए|बताओ|क्या है|कैसे|உதவி|விவரம்|சந்தேகம்|புரியவில்லை|எப்படி|సహాయం|వివరాలు|సందేహం|అర్థం కాలేదు|ఎలా)/.test(text);
const fillerWords = ['नमस्ते', 'हाँ', 'हां', 'ठीक है', 'धन्यवाद', 'ओके', 'जी', 'வணக்கம்', 'சரி', 'நன்றி', 'ஓகே', 'ஆம்', 'ஆமாம்', 'నమస్తే', 'నమస్కారం', 'సరే', 'ధన్యవాదాలు', 'ఓకే', 'అవును', 'ok', 'okay', 'k', 'thanks', 'thank you', 'thankyou', 'yes', 'no', 'hi', 'hello', 'done', 'fine', 'great', 'nice'];
const now = $now.setZone('Asia/Kolkata').toFormat('yyyy-MM-dd HH:mm:ss');

function parseAmount(s) {
  const t = String(s).replace(/[०-९]/g, d => String('०१२३४५६७८९'.indexOf(d))).toLowerCase().replace(/,/g, '').replace(/₹|rs\.?|inr|rupees?/g, ' ');
  const m = t.match(/(\d+(?:\.\d+)?)\s*(k|thousand|lakh|lac|l)?\b/);
  if (!m) return null;
  let n = parseFloat(m[1]);
  const u = m[2];
  if (u === 'k' || u === 'thousand') n *= 1000;
  if (u === 'l' || u === 'lakh' || u === 'lac') n *= 100000;
  return n;
}

function appendItems(prev, add) {
  if (!add) return prev || '';
  return prev ? prev + ' | ' + add : add;
}

const rec = {
  phone: phone,
  whatsapp_name: (contact.profile && contact.profile.name) || existing.whatsapp_name || '',
  business_details: existing.business_details || '',
  category: existing.category || '',
  interested_items: existing.interested_items || '',
  order_value: existing.order_value || '',
  order_photo: existing.order_photo || '',
  first_contact: existing.first_contact || now,
};

let route = 'done';
let newStage = rawStage;
let handoffReason = '';
function retryOrHandoff(retryRoute) {
  if (tries + 1 >= 2) {
    route = 'handoff';
    handoffReason = 'Confusing answers - could not get a valid reply after 2 tries';
    newStage = stage;
  } else {
    route = retryRoute;
    newStage = stage + '#' + (tries + 1);
  }
}

if (type === 'image') {
  route = 'photo';
  rec.order_photo = 'Yes - ' + now;
  newStage = rawStage;
} else if (stage && stage !== 'awaiting_language' && type === 'text' && (wantsHuman || wantsHumanHi)) {
  route = 'handoff';
  handoffReason = 'Asked to speak to a sales associate / human';
} else if (stage && stage !== 'escalated_to_sales' && stage !== 'awaiting_language' && type === 'text' && (wantsInfo || wantsInfoHi)) {
  route = 'handoff';
  handoffReason = 'Needs more information';
  if (stage === 'awaiting_order_value' || stage === 'rate_list_sent') rec.interested_items = appendItems(rec.interested_items, text);
} else if (!stage) {
  route = 'ask_language';
  newStage = 'awaiting_language';
} else if (stage === 'awaiting_language') {
  const l = text.toLowerCase();
  if (replyId === 'lang_hi' || /hindi|हिंदी|हिन्दी/.test(l)) {
    lang = 'hi';
    route = 'greet';
    newStage = 'awaiting_details';
  } else if (replyId === 'lang_ta' || /tamil|தமிழ்/.test(l)) {
    lang = 'ta';
    route = 'greet';
    newStage = 'awaiting_details';
  } else if (replyId === 'lang_te' || /telugu|తెలుగు/.test(l)) {
    lang = 'te';
    route = 'greet';
    newStage = 'awaiting_details';
  } else if (replyId === 'lang_en' || /english|इंग्लिश|अंग्रेज़ी|अंग्रेजी/.test(l)) {
    lang = 'en';
    route = 'greet';
    newStage = 'awaiting_details';
  } else {
    retryOrHandoff('ask_language');
  }
} else if (stage === 'awaiting_details') {
  const fillers = ['hi', 'hii', 'hiii', 'hello', 'helo', 'hey', 'namaste', 'ok', 'okay', 'k', 'yes', 'no', 'thanks', 'thank you', 'thankyou', 'good morning', 'good afternoon', 'good evening', 'catalogue', 'catalog', 'price', 'rate', 'rates'];
  const clean = text.toLowerCase().replace(/[^a-z\u0900-\u097F\u0B80-\u0BFF\u0C00-\u0C7F ]/g, '').trim();
  const valid = type === 'text' && clean.length >= 3 && !fillers.includes(clean) && !fillerWords.includes(clean);
  if (valid) {
    route = 'ask_category';
    rec.business_details = text;
    newStage = 'awaiting_category';
  } else {
    retryOrHandoff('details_retry');
  }
} else if (stage === 'awaiting_category') {
  const cats = ['shopkeeper', 'retailer', 'wholesaler', 'reseller', 'new business', 'other'];
  const isListReply = type === 'interactive';
  const catNames = { shopkeeper: 'Shopkeeper', retailer: 'Retailer', wholesaler: 'Wholesaler', reseller: 'Reseller', new_business: 'New Business', other: 'Other' };
  const hiCats = { 'दुकानदार': 'Shopkeeper', 'रिटेलर': 'Retailer', 'होलसेलर': 'Wholesaler', 'थोक': 'Wholesaler', 'रीसेलर': 'Reseller', 'नया': 'New Business', 'अन्य': 'Other', 'கடைக்காரர்': 'Shopkeeper', 'ரீடெய்லர்': 'Retailer', 'மொத்த': 'Wholesaler', 'ரீசெல்லர்': 'Reseller', 'புதிய': 'New Business', 'மற்றவை': 'Other', 'షాప్': 'Shopkeeper', 'రిటైలర్': 'Retailer', 'హోల్': 'Wholesaler', 'రీసెల్లర్': 'Reseller', 'కొత్త': 'New Business', 'ఇతర': 'Other' };
  const enMatch = cats.find(c => text.toLowerCase().includes(c));
  const hiMatch = Object.keys(hiCats).find(h => text.includes(h));
  const matched = catNames[replyId] || (enMatch ? catNames[enMatch.replace(' ', '_')] : '') || (hiMatch ? hiCats[hiMatch] : '');
  if (isListReply || matched) {
    route = 'send_catalogue';
    rec.category = matched || text || 'Other';
    newStage = 'awaiting_order_value';
  } else {
    retryOrHandoff('ask_category');
  }
} else if (stage === 'awaiting_order_value') {
  const lowSel = replyId === 'ov_low' || /less than|से कम|கீழ்|కంటే తక్కువ/i.test(text);
  const highSel = replyId === 'ov_high' || /or more|या अधिक|से ज़्यादा|से ज्यादा|அல்லது மேல்|లేదా ఎక్కువ/i.test(text);
  const typed = (lowSel || highSel) ? null : parseAmount(text);
  const amt = highSel ? 10000 : (lowSel ? 0 : typed);
  if (amt === null) {
    rec.interested_items = appendItems(rec.interested_items, text);
    retryOrHandoff('order_retry');
  } else if (amt < 10000) {
    route = 'order_low';
    rec.order_value = lowSel ? 'Less than ₹10,000' : '₹' + amt;
    newStage = 'rate_list_sent';
  } else {
    route = 'order_high';
    rec.order_value = highSel ? '₹10,000 or more' : '₹' + amt;
    newStage = 'escalated_to_sales';
  }
} else {
  rec.interested_items = appendItems(rec.interested_items, text);
  const isFiller = fillerWords.includes(lower.trim()) || fillerWords.includes(lower.replace(/[^a-z ]/g, '').trim()) || !lower.replace(/[^a-z0-9\u0900-\u097F\u0B80-\u0BFF\u0C00-\u0C7F]/g, '');
  if (stage === 'rate_list_sent' && type === 'text' && !isFiller) {
    route = 'handoff';
    handoffReason = 'Needs more information / follow-up after receiving the rate list';
  }
}

